INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mendelian Inheritance','easy','mcq','A couple has a child with an autosomal recessive disorder. What is the probability that their next child will be affected?','["A. 25%","B. 50%","C. 75%","D. 100%"]','A','When both parents are carriers (Aa x Aa), each pregnancy has a 25% chance of producing an affected child (aa). This probability is independent for each pregnancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mendelian Inheritance','easy','mcq','A man with an autosomal dominant disorder (heterozygous) has children with an unaffected woman. What fraction of their children are expected to be affected?','["A. 0%","B. 25%","C. 50%","D. 100%"]','C','Autosomal dominant inheritance with one heterozygous parent (Aa x aa) yields a 1:1 ratio of affected (Aa) to unaffected (aa) offspring, giving a 50% probability for each child.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mendelian Inheritance','medium','mcq','In a pedigree, a disorder skips generations and affects both males and females equally, with unaffected carrier parents. Which inheritance pattern is most consistent?','["A. Autosomal dominant","B. Autosomal recessive","C. X-linked recessive","D. Mitochondrial"]','B','Autosomal recessive disorders characteristically skip generations because carriers are phenotypically normal. Both sexes are equally affected and two carrier parents can produce affected children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mendelian Inheritance','medium','mcq','Which of the following is a characteristic feature of autosomal dominant inheritance?','["A. Parents are usually unaffected carriers","B. Males are more severely affected than females","C. Affected individuals are usually heterozygous","D. The disease only appears in homozygotes"]','C','In autosomal dominant disorders, a single copy of the mutant allele is sufficient to cause disease; therefore most affected individuals are heterozygous. Homozygosity is rare and often lethal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mendelian Inheritance','medium','mcq','Two unaffected parents have four children: one affected daughter and three unaffected sons. Which of the following inheritance patterns is most likely?','["A. Autosomal dominant","B. X-linked recessive","C. Autosomal recessive","D. Y-linked"]','C','An affected daughter from two unaffected parents is inconsistent with X-linked recessive (which would preferentially affect sons). Autosomal recessive best explains this pedigree with two carrier parents producing an affected child.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mendelian Inheritance','medium','mcq','A woman is a known carrier of an autosomal recessive disease. Her partner is also a carrier. What is the probability of having a carrier (but unaffected) child?','["A. 25%","B. 50%","C. 75%","D. 100%"]','B','From an Aa x Aa cross, the offspring ratio is 1 AA : 2 Aa : 1 aa. The two Aa genotypes represent 50% of all offspring  --  these are carriers who are phenotypically unaffected.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mendelian Inheritance','hard','mcq','A man affected with an autosomal dominant condition with 80% penetrance has children with an unaffected woman. What is the actual probability that a child will manifest the disease?','["A. 10%","B. 25%","C. 40%","D. 50%"]','C','The probability of inheriting the dominant allele is 50%. With 80% penetrance, only 80% of those who inherit the allele will manifest disease. Therefore 50% x 80% = 40% of children will be affected.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mendelian Inheritance','hard','mcq','In Mendel''s law of independent assortment, which of the following conditions is REQUIRED for the law to hold true?','["A. Genes must be on the same chromosome","B. Genes must be located on non-homologous chromosomes or far apart on the same chromosome","C. Genes must encode proteins with similar functions","D. At least one gene must show incomplete dominance"]','B','Independent assortment requires genes to be on non-homologous (different) chromosomes, or if on the same chromosome, to be far enough apart that crossing-over effectively unlinks them. Closely linked genes on the same chromosome violate this law.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mendelian Inheritance','medium','mcq','Which of the following diseases follows autosomal dominant inheritance with variable expressivity?','["A. Cystic fibrosis","B. Phenylketonuria","C. Neurofibromatosis type 1","D. Tay-Sachs disease"]','C','Neurofibromatosis type 1 (NF1) is an autosomal dominant condition showing highly variable expressivity  --  manifestations range from cafe-au-lait spots alone to severe neurofibromas and learning disability.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mendelian Inheritance','easy','mcq','Cystic fibrosis is caused by mutations in the CFTR gene and follows autosomal recessive inheritance. A child is affected. What is the most likely genotype of each parent?','["A. Homozygous dominant (AA)","B. Heterozygous carrier (Aa)","C. Homozygous recessive (aa)","D. Hemizygous"]','B','For an autosomal recessive child to be born, both parents must each carry one mutant allele (Aa). They are phenotypically unaffected carriers who each transmit the recessive allele to the affected offspring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','X-linked & Y-linked Disorders','easy','mcq','A boy is diagnosed with haemophilia A. His mother is a carrier. What is the probability that his maternal uncle (mother''s brother) also has haemophilia A?','["A. 0%","B. 25%","C. 50%","D. 100%"]','C','The boy''s mother is a carrier (XH Xh). Her brothers each received either the normal or affected X chromosome from their mother (the grandmother), giving a 50% chance of haemophilia in each maternal male relative.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','X-linked & Y-linked Disorders','easy','mcq','Duchenne muscular dystrophy (DMD) is caused by a mutation in which protein?','["A. Dystroglycan","B. Dystrophin","C. Desmin","D. Dysferlin"]','B','DMD results from frameshift or nonsense mutations in the dystrophin gene (DMD) on Xp21, leading to complete absence of the dystrophin protein, which normally anchors the cytoskeleton to the extracellular matrix in muscle fibres.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','X-linked & Y-linked Disorders','medium','mcq','A female carrier of X-linked recessive haemophilia A has children with an unaffected male. What proportion of their daughters will be carriers?','["A. 0%","B. 25%","C. 50%","D. 100%"]','C','A carrier mother (XH Xh) x normal father (XH Y). Daughters receive XH from father and either XH or Xh from mother  --  50% will be carriers (XH Xh) and 50% will be normal (XH XH).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','X-linked & Y-linked Disorders','medium','mcq','Becker muscular dystrophy differs from Duchenne muscular dystrophy primarily because in Becker MD:','["A. The dystrophin gene is on an autosome","B. There is a frameshift mutation producing no protein","C. The mutation maintains the reading frame, producing a partially functional dystrophin","D. It is caused by a trinucleotide repeat expansion"]','C','Becker MD is caused by in-frame deletions in the dystrophin gene that preserve the reading frame, resulting in a truncated but partially functional dystrophin protein. This leads to a milder, later-onset phenotype compared to DMD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','X-linked & Y-linked Disorders','medium','mcq','Turner syndrome (45,X) presents with which of the following clinical features?','["A. Tall stature, macroorchidism, intellectual disability","B. Short stature, webbed neck, primary amenorrhoea, streak gonads","C. Gynaecomastia, small testes, tall stature","D. Coarse facial features, large tongue, simian crease"]','B','Turner syndrome (45,X) is characterised by short stature, webbed neck (pterygium colli), shield chest, streak gonads causing primary amenorrhoea, and infertility. It is the most common cause of primary amenorrhoea.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','X-linked & Y-linked Disorders','medium','mcq','Klinefelter syndrome (47,XXY) is associated with which of the following?','["A. 45,X karyotype","B. Hypergonadism and increased testosterone","C. Hypogonadism, small firm testes, gynaecomastia, and infertility","D. Short stature and webbed neck"]','C','Klinefelter syndrome (47,XXY) results in hypergonadotrophic hypogonadism with small firm testes, gynaecomastia, azoospermia leading to infertility, and often tall stature with long limbs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','X-linked & Y-linked Disorders','hard','mcq','A woman is affected with an X-linked recessive disorder. What must be true about her father?','["A. He is an unaffected carrier","B. He must be affected with the disorder","C. He has a normal genotype","D. The disorder must have arisen by new mutation in her"]','B','For a female to be affected with an X-linked recessive disorder, she must be homozygous (Xa Xa). She must have received one affected X from each parent, so her father must be hemizygous affected (Xa Y) for the disorder.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','X-linked & Y-linked Disorders','hard','mcq','Fragile X syndrome is caused by which molecular mechanism?','["A. Expansion of a CGG trinucleotide repeat in the FMR1 gene on the X chromosome","B. Deletion of chromosome 15q11","C. Nonsense mutation in the dystrophin gene","D. Trisomy of the X chromosome"]','A','Fragile X syndrome results from expansion of a CGG trinucleotide repeat (>200 repeats) in the 5 UTR of the FMR1 gene on Xq27.3, causing hypermethylation and silencing of FMRP production. It is the most common inherited cause of intellectual disability in males.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','X-linked & Y-linked Disorders','medium','mcq','Which coagulation factor is deficient in haemophilia B?','["A. Factor VIII","B. Factor IX","C. Factor XI","D. Von Willebrand factor"]','B','Haemophilia B (Christmas disease) is an X-linked recessive disorder caused by deficiency of coagulation factor IX (encoded on the X chromosome). Haemophilia A involves factor VIII deficiency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','X-linked & Y-linked Disorders','easy','mcq','Y-linked (holandric) inheritance is characterised by which of the following patterns?','["A. Transmission from father to all sons only","B. Transmission from mother to all daughters","C. Equal probability of transmission to sons and daughters","D. Skipping of generations is common"]','A','Y-linked genes are present only in males and pass exclusively from father to all sons (since sons always receive the Y chromosome from their father). Daughters never inherit Y-linked conditions.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Chromosomal Abnormalities','easy','mcq','Down syndrome is most commonly caused by which chromosomal abnormality?','["A. Monosomy 21","B. Trisomy 21 due to meiotic non-disjunction","C. Deletion of chromosome 21q","D. Translocation of chromosome 7 onto chromosome 21"]','B','The most common cause of Down syndrome (~95% of cases) is trisomy 21 resulting from non-disjunction during meiosis I or II, typically in the maternal egg, leading to three copies of chromosome 21.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Chromosomal Abnormalities','easy','mcq','Which of the following is a clinical feature of Down syndrome (trisomy 21)?','["A. Rocker-bottom feet and overlapping fingers","B. Hypotonia, epicanthal folds, simian crease, and congenital heart defects","C. Microcephaly, holoprosencephaly, polydactyly","D. Clenched fists with overlapping index finger"]','B','Down syndrome features include hypotonia, flat facial profile, epicanthal folds, upward-slanting palpebral fissures, Brushfield spots, simian palmar crease, and congenital heart defects (most commonly AVSD or VSD) in ~40% of cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Chromosomal Abnormalities','medium','mcq','Edwards syndrome is caused by trisomy of which chromosome?','["A. Chromosome 13","B. Chromosome 21","C. Chromosome 18","D. Chromosome 22"]','C','Edwards syndrome is caused by trisomy 18. It presents with clenched fists with overlapping fingers, rocker-bottom feet, micrognathia, cardiac defects, and is associated with a very poor prognosis with most affected infants dying within the first year.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Chromosomal Abnormalities','medium','mcq','Patau syndrome (trisomy 13) is characterised by which of the following features?','["A. Broad thumbs and big toes, beaked nose","B. Holoprosencephaly, microcephaly, cleft lip/palate, polydactyly","C. Rocker-bottom feet, clenched fists, micrognathia","D. Webbed neck, streak gonads, primary amenorrhoea"]','B','Patau syndrome (trisomy 13) is characterised by midline defects: holoprosencephaly, midline cleft lip and palate, microcephaly, polydactyly, microphthalmia, and congenital heart defects. Prognosis is very poor.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Chromosomal Abnormalities','medium','mcq','Cri-du-chat syndrome results from which chromosomal abnormality?','["A. Trisomy 5","B. Deletion of the short arm of chromosome 5 (5p-)","C. Translocation between chromosomes 5 and 21","D. Pericentric inversion of chromosome 5"]','B','Cri-du-chat (cry of the cat) syndrome is caused by deletion of the short arm of chromosome 5 (5p-). It presents with a high-pitched cat-like cry in infancy, microcephaly, widely-spaced eyes, intellectual disability, and low birth weight.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Chromosomal Abnormalities','medium','mcq','A mother carries a balanced Robertsonian translocation between chromosomes 14 and 21 [t(14;21)]. What is the approximate risk that her child will have Down syndrome?','["A. ~1%","B. ~33%","C. ~10-15%","D. ~100%"]','C','A female carrier of a t(14;21) Robertsonian translocation has approximately a 10-15% empirical risk of a Down syndrome child (theoretically 33% of viable pregnancies, but many are non-viable). This distinguishes translocation Down syndrome from trisomy 21.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Chromosomal Abnormalities','hard','mcq','A balanced reciprocal translocation carrier is phenotypically normal. During meiosis, what can occur that produces chromosomally unbalanced offspring?','["A. Anaphase lag leading to monosomy","B. 3:1 or 2:2 malsegregation of the translocation quadrivalent","C. Non-disjunction of sex chromosomes only","D. Uniparental disomy of both translocation chromosomes"]','B','During meiosis in a balanced translocation carrier, the four chromosomes form a quadrivalent. Alternate segregation produces balanced offspring; adjacent-1, adjacent-2, or 3:1 segregation produces chromosomally unbalanced offspring with partial trisomy or monosomy.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Chromosomal Abnormalities','hard','mcq','Which maternal age-related risk is most accurately described?','["A. Risk of X-linked disorders increases with maternal age","B. Risk of trisomy 21 increases exponentially with advanced maternal age due to prolonged arrest of oocytes in meiosis I","C. Risk of chromosomal deletions increases with advanced paternal age","D. Advanced maternal age primarily increases the risk of uniparental disomy"]','B','The risk of trisomy 21 (and other trisomies) rises markedly with advanced maternal age. Human oocytes are arrested at prophase I for decades; prolonged arrest increases susceptibility to non-disjunction, particularly at meiosis I.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Chromosomal Abnormalities','medium','mcq','Which of the following syndromes is associated with a deletion at chromosome 22q11.2?','["A. Williams syndrome","B. DiGeorge syndrome (22q11.2 deletion syndrome)","C. Angelman syndrome","D. Wolf-Hirschhorn syndrome"]','B','DiGeorge syndrome (22q11.2 deletion syndrome / velocardiofacial syndrome) involves haploinsufficiency of TBX1 at 22q11.2, causing cardiac outflow tract defects, absent/hypoplastic thymus (T-cell deficiency), hypocalcaemia, and palatal abnormalities.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Chromosomal Abnormalities','easy','mcq','Which prenatal diagnostic test can detect chromosomal abnormalities by directly counting chromosomes from fetal cells?','["A. Maternal serum AFP measurement","B. Amniocentesis with karyotyping","C. Nuchal translucency ultrasound alone","D. Cell-free fetal DNA sequencing (NIPT)"]','B','Amniocentesis (performed at 15-20 weeks) obtains amniotic fluid containing fetal cells; these are cultured and karyotyped to directly count and visualise chromosomes, definitively diagnosing trisomies, sex chromosome abnormalities, and structural rearrangements.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Molecular Genetics Techniques','easy','mcq','Which enzyme is essential for the polymerase chain reaction (PCR) and is stable at high temperatures?','["A. RNA polymerase","B. DNA ligase","C. Taq polymerase (thermostable DNA polymerase)","D. Reverse transcriptase"]','C','Taq polymerase, derived from Thermus aquaticus, is a thermostable DNA polymerase that remains active during the high-temperature denaturation steps of PCR (94-96 degrees C), making PCR cycles feasible without re-adding enzyme.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Molecular Genetics Techniques','easy','mcq','Southern blotting is used to detect which type of molecule?','["A. RNA","B. Protein","C. DNA","D. Lipid"]','C','Southern blotting detects specific DNA sequences. DNA is digested with restriction enzymes, separated by gel electrophoresis, transferred to a membrane, and hybridised with a labelled probe. Northern blotting detects RNA and Western blotting detects protein.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Molecular Genetics Techniques','medium','mcq','Fluorescence in situ hybridisation (FISH) is most useful for detecting which of the following?','["A. Single nucleotide polymorphisms","B. Chromosomal deletions, duplications, and translocations at the cytogenetic level","C. mRNA expression levels","D. Protein-protein interactions"]','B','FISH uses fluorescently labelled DNA probes that hybridise to specific chromosomal loci. It detects microdeletions (e.g., 22q11.2), chromosomal translocations (e.g., BCR-ABL in CML), and gene copy number changes at a resolution below standard karyotyping.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Molecular Genetics Techniques','medium','mcq','In the Sanger dideoxy chain-termination sequencing method, what is the role of ddNTPs (dideoxynucleotide triphosphates)?','["A. They provide energy for polymerisation","B. They terminate chain elongation when incorporated because they lack a 3-OH group","C. They label the primer fluorescently","D. They denature the template strand"]','B','Dideoxynucleotides (ddNTPs) lack the 3-OH group required for phosphodiester bond formation. When incorporated by DNA polymerase, they cause chain termination, producing a population of fragments of all lengths that are then separated to read the sequence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Molecular Genetics Techniques','medium','mcq','A karyotype reveals 46 chromosomes with a Philadelphia chromosome. What molecular rearrangement does this represent?','["A. Trisomy 22","B. Deletion of chromosome 9","C. Reciprocal translocation between chromosomes 9 and 22, t(9;22)","D. Inversion of chromosome 22"]','C','The Philadelphia chromosome is a shortened chromosome 22 resulting from a reciprocal translocation t(9;22)(q34;q11). This creates the BCR-ABL1 fusion gene encoding a constitutively active tyrosine kinase, driving chronic myeloid leukaemia (CML).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Molecular Genetics Techniques','medium','mcq','Reverse transcriptase PCR (RT-PCR) begins with which step that distinguishes it from standard PCR?','["A. Denaturation of genomic DNA at 95 degrees C","B. Conversion of mRNA to cDNA using reverse transcriptase","C. Amplification of genomic DNA directly","D. Restriction enzyme digestion of the template"]','B','RT-PCR starts with extraction of mRNA, which is then converted to complementary DNA (cDNA) by reverse transcriptase. The cDNA is then used as the template for PCR amplification. This technique detects gene expression and is used diagnostically and in research.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Molecular Genetics Techniques','hard','mcq','Array comparative genomic hybridisation (array CGH) is superior to conventional karyotyping for detecting which type of abnormality?','["A. Whole chromosome aneuploidies such as trisomy 21","B. Copy number variants (CNVs) and submicroscopic deletions/duplications below 5-10 Mb resolution","C. Balanced translocations between chromosomes","D. Uniparental disomy"]','B','Array CGH can detect copy number variants (CNVs) as small as a few kilobases by comparing patient and reference DNA hybridised to thousands of genomic probes. However, it cannot detect balanced rearrangements (no net copy number change) or low-level mosaicism.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Molecular Genetics Techniques','hard','mcq','Next-generation sequencing (NGS) differs from Sanger sequencing primarily in that NGS:','["A. Can only sequence mitochondrial DNA","B. Uses dideoxy chain termination exclusively","C. Requires a known DNA sequence for primer design at every position","D. Sequences millions of DNA fragments in parallel (massively parallel sequencing)"]','D','NGS platforms perform massively parallel sequencing of millions of short DNA fragments simultaneously, enabling rapid whole-genome or whole-exome sequencing at low cost per base. Sanger sequencing reads one fragment at a time and is better for targeted, high-accuracy sequencing of specific regions.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Molecular Genetics Techniques','medium','mcq','Which technique uses restriction fragment length polymorphisms (RFLPs) to track inheritance of a disease allele within a family?','["A. FISH","B. Linkage analysis using RFLPs as markers","C. Array CGH","D. RT-PCR"]','B','RFLP-based linkage analysis detects variation in restriction enzyme cut sites near a disease gene. By tracking which RFLP allele co-segregates with disease in a family, the disease allele can be indirectly identified even before the gene is cloned.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Molecular Genetics Techniques','easy','mcq','What is the purpose of gel electrophoresis in molecular genetics?','["A. To separate DNA, RNA, or protein fragments by size using an electric field","B. To amplify specific DNA sequences","C. To hybridise complementary DNA strands","D. To digest DNA at specific restriction sites"]','A','Gel electrophoresis separates nucleic acid or protein molecules by size as they migrate through an agarose or polyacrylamide gel under an electric field  --  smaller fragments migrate faster. It is used to visualise PCR products, restriction digests, and sequencing ladders.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Population Genetics','easy','mcq','The Hardy-Weinberg equilibrium states that allele and genotype frequencies remain constant in a population provided which of the following conditions is met?','["A. Natural selection favours the heterozygote","B. The population is large, random mating occurs, no mutation, no migration, and no selection","C. Genetic drift is occurring","D. Inbreeding is present"]','B','Hardy-Weinberg equilibrium requires: large population size, random mating, no mutation, no gene flow (migration), and no natural selection. When these conditions hold, allele and genotype frequencies remain stable across generations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Population Genetics','easy','mcq','If the frequency of an autosomal recessive disease in a population is 1 in 10,000, what is the carrier frequency (assuming Hardy-Weinberg equilibrium)?','["A. 1 in 50","B. 1 in 100","C. 1 in 500","D. 1 in 200"]','A','Disease frequency q^2 = 1/10,000, so q = 1/100. Carrier frequency = 2pq which is approximately 2q (since p is approximately 1) = 2/100 = 1/50. Therefore approximately 1 in 50 individuals is a carrier.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Population Genetics','medium','mcq','Genetic drift is most likely to have a significant effect in which type of population?','["A. A large cosmopolitan population","B. A population under strong positive selection","C. A small isolated population","D. A population with high immigration rates"]','C','Genetic drift  --  random changes in allele frequency  --  has the greatest impact in small populations. In small isolated populations, chance events can dramatically alter allele frequencies, potentially leading to fixation or loss of alleles independent of natural selection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Population Genetics','medium','mcq','The founder effect is a special case of which population genetics phenomenon?','["A. Natural selection","B. Mutation pressure","C. Gene flow","D. Genetic drift"]','D','The founder effect is a form of genetic drift that occurs when a small number of individuals establish a new population. The new population''s gene pool is a non-representative sample of the original, leading to higher frequencies of certain alleles (e.g., high frequency of specific genetic diseases in Amish communities).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Population Genetics','medium','mcq','Heterozygote advantage (balanced polymorphism) is best illustrated by which example?','["A. ABO blood group incompatibility","B. Sickle cell trait (HbAS) providing protection against Plasmodium falciparum malaria","C. Cystic fibrosis carriers having higher fertility","D. Phenylketonuria carriers having enhanced phenylalanine metabolism"]','B','Sickle cell trait (HbAS) demonstrates heterozygote advantage: carriers have reduced severity of P. falciparum malaria compared to normal homozygotes, while avoiding the severe anaemia of HbSS. This maintains both alleles at high frequency in malaria-endemic regions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Population Genetics','medium','mcq','In a Hardy-Weinberg equilibrium population, if the allele frequency of A is 0.7 and a is 0.3, what is the expected frequency of heterozygotes (Aa)?','["A. 0.09","B. 0.21","C. 0.49","D. 0.42"]','D','Heterozygote frequency = 2pq = 2 x 0.7 x 0.3 = 0.42. This represents 42% of the population. The genotype frequencies are: AA = p^2 = 0.49, Aa = 2pq = 0.42, aa = q^2 = 0.09.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Population Genetics','hard','mcq','A bottleneck effect differs from a founder effect in that:','["A. A bottleneck involves a sudden dramatic reduction in an existing population''s size, while a founder effect involves a small group migrating to establish a new population","B. A bottleneck increases genetic diversity while a founder effect decreases it","C. A bottleneck only affects mitochondrial DNA","D. A founder effect requires natural selection while a bottleneck does not"]','A','A bottleneck occurs when a large existing population is drastically reduced in size by a catastrophic event (disease, famine, disaster), leading to loss of genetic variation. The founder effect occurs when a small subset emigrates to form a new population, also reducing diversity.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Population Genetics','hard','mcq','Consanguinity (mating between relatives) is most likely to increase the frequency of which type of genetic disorder in offspring?','["A. Autosomal recessive disorders","B. X-linked dominant disorders","C. Autosomal dominant disorders","D. Chromosomal trisomies"]','A','Consanguinity increases the probability that both parents carry the same rare recessive allele inherited from a common ancestor, dramatically raising the risk of homozygosity in offspring. This preferentially increases risk of autosomal recessive disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Population Genetics','medium','mcq','Gene flow between populations tends to have which effect on genetic variation between those populations?','["A. Increase genetic differences between populations","B. Decrease genetic differences between populations by homogenising allele frequencies","C. Have no effect on allele frequencies","D. Increase the rate of new mutations"]','B','Gene flow (migration and interbreeding between populations) transfers alleles between populations, reducing genetic differentiation and homogenising allele frequencies. It acts as a cohesive force counteracting the divergence caused by drift and selection.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Population Genetics','easy','mcq','In Hardy-Weinberg equilibrium, if p + q = 1, and p^2 + 2pq + q^2 = 1, what do p and q represent?','["A. Genotype frequencies of AA and aa","B. The frequencies of two alleles at a biallelic locus","C. The frequencies of dominant and recessive phenotypes","D. The mutation rates of two alleles"]','B','In the Hardy-Weinberg equation, p and q represent the frequencies of two alleles (e.g., A and a) at a locus in a population, where p + q = 1. The terms p^2, 2pq, and q^2 represent the frequencies of the AA, Aa, and aa genotypes respectively.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Epigenetics','easy','mcq','DNA methylation in mammalian cells most commonly occurs at which sequence context?','["A. AT dinucleotides","B. CpG dinucleotides (cytosine followed by guanine)","C. Telomeric TTAGGG repeats","D. Trinucleotide CAG repeats"]','B','In mammals, DNA methylation predominantly occurs at cytosine residues within CpG dinucleotides, catalysed by DNA methyltransferases (DNMTs). Methylation of promoter CpG islands typically represses gene transcription.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Epigenetics','easy','mcq','Genomic imprinting results in which of the following?','["A. Equal expression of both maternal and paternal alleles","B. Expression of only one parental allele, determined by the parent of origin","C. Random expression of either the maternal or paternal allele in each cell","D. Silencing of both alleles simultaneously"]','B','Genomic imprinting is a form of epigenetic regulation in which the expression of a gene depends on the parent from whom it was inherited. Imprinted genes are monoallelically expressed in a parent-of-origin-specific manner due to differential methylation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Epigenetics','medium','mcq','Prader-Willi syndrome arises when the paternal copy of chromosome 15q11-q13 is deleted or silenced. What is the mechanism when there is no deletion but the condition still occurs?','["A. A new mutation in the maternal SNRPN gene","B. Maternal uniparental disomy (both copies of chromosome 15 inherited from the mother)","C. Methylation of the paternal allele by the mother","D. Trisomy 15 with loss of one maternal copy"]','B','When there is no deletion, Prader-Willi syndrome can result from maternal uniparental disomy  --  the child inherits both copies of chromosome 15 from the mother. Since the maternal alleles at 15q11-q13 are normally imprinted (silenced), no paternal gene expression occurs, producing the Prader-Willi phenotype.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Epigenetics','medium','mcq','A child presents with severe intellectual disability, seizures, absence of speech, and an inappropriately happy, puppet-like gait. Which epigenetic mechanism is responsible?','["A. Deletion of paternal 15q11-q13 causing Prader-Willi syndrome","B. Deletion of maternal 15q11-q13 or paternal uniparental disomy causing Angelman syndrome","C. Expansion of CGG repeats on chromosome X causing Fragile X","D. Methylation of chromosome 11p15 causing Beckwith-Wiedemann syndrome"]','B','Angelman syndrome results from loss of function of the maternal UBE3A allele at 15q11-q13 (usually by deletion of the maternal copy or paternal UPD). UBE3A is only expressed from the maternal allele in neurons; its loss causes the characteristic features including the happy puppet phenotype.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Epigenetics','medium','mcq','X-inactivation (lyonisation) in females results in which of the following?','["A. Complete inactivation of both X chromosomes in each cell","B. Random inactivation of one X chromosome in each somatic cell, forming a Barr body","C. Preferential inactivation of the maternal X chromosome","D. Inactivation of the Y chromosome in male cells"]','B','During early embryogenesis, one X chromosome in each female somatic cell is randomly inactivated and remains condensed as a Barr body. This process is governed by the XIST gene and ensures dosage compensation between XX females and XY males.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Epigenetics','medium','mcq','Histone acetylation by histone acetyltransferases (HATs) generally has which effect on gene expression?','["A. Represses gene expression by compacting chromatin","B. Activates gene expression by relaxing chromatin structure","C. Causes DNA methylation at CpG islands","D. Promotes heterochromatin formation"]','B','Acetylation of lysine residues on histone tails by HATs neutralises the positive charge of histones, weakening their interaction with negatively charged DNA. This relaxes chromatin into euchromatin, making DNA accessible to transcription factors and promoting gene expression.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Epigenetics','hard','mcq','Beckwith-Wiedemann syndrome is caused by dysregulation of imprinting at chromosome 11p15.5. Which finding distinguishes loss of imprinting of IGF2 as the mechanism?','["A. Biallelic expression of IGF2, leading to overgrowth","B. Biallelic silencing of IGF2, leading to growth restriction","C. Deletion of the H19 locus only","D. Methylation of the CDKN1C gene"]','A','Normally only the paternal IGF2 allele is expressed. Loss of imprinting (LOI) of IGF2 results in biallelic expression, doubling IGF2 protein levels and causing the overgrowth features of Beckwith-Wiedemann syndrome (macrosomia, macroglossia, omphalocele, predisposition to Wilms tumour).','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Epigenetics','hard','mcq','Which of the following best describes the concept of epigenetic inheritance?','["A. Changes in DNA sequence passed from parent to offspring","B. Heritable changes in gene expression that do not involve alterations in the DNA sequence","C. Random mutations accumulating over successive generations","D. Mendelian transmission of dominant alleles only"]','B','Epigenetic inheritance involves heritable changes in gene expression patterns (such as DNA methylation marks and histone modifications) that are transmitted through cell division and sometimes across generations without any change in the underlying DNA sequence.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Epigenetics','medium','mcq','In which of the following disorders does X-inactivation skewing lead to carrier females being symptomatic?','["A. Cystic fibrosis","B. Haemophilia A in some carrier women with skewed X-inactivation","C. Marfan syndrome","D. Huntington disease"]','B','Normally, carrier females for X-linked recessive disorders are unaffected due to random X-inactivation. However, if the normal X chromosome is preferentially inactivated (skewed X-inactivation), some carrier women may have significant expression of the abnormal allele and manifest symptoms of haemophilia A.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Epigenetics','easy','mcq','The number of Barr bodies in a cell equals:','["A. The total number of sex chromosomes","B. The number of X chromosomes minus one","C. The number of Y chromosomes","D. Half the total chromosome number"]','B','The number of Barr bodies equals the number of inactivated X chromosomes, which is the total number of X chromosomes minus one (one X always remains active). A normal female (XX) has 1 Barr body; a Klinefelter male (XXY) has 1 Barr body; a triple X female (XXX) has 2 Barr bodies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Oncogenetics','easy','mcq','According to Knudson''s two-hit hypothesis, how many mutational events are required to inactivate a tumour suppressor gene?','["A. One hit in a single allele","B. Two hits  --  one in each allele of the tumour suppressor gene","C. Three hits involving two alleles and an epigenetic event","D. One germline hit is always sufficient"]','B','Knudson''s two-hit hypothesis states that both alleles of a tumour suppressor gene must be inactivated for tumorigenesis. In hereditary cancer syndromes, the first hit is inherited (germline), and only one somatic mutation is needed; in sporadic cancers, both hits occur somatically.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Oncogenetics','easy','mcq','BRCA1 and BRCA2 are best classified as which type of cancer gene?','["A. Proto-oncogenes","B. DNA repair genes acting as tumour suppressor genes","C. Oncogenes with gain-of-function mutations","D. Telomerase activating genes"]','B','BRCA1 and BRCA2 encode proteins involved in homologous recombination DNA double-strand break repair. They act as tumour suppressors  --  loss of both alleles leads to genomic instability and greatly elevated risk of breast and ovarian cancers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Oncogenetics','medium','mcq','A proto-oncogene becomes an oncogene through which mechanism?','["A. Loss of both alleles (two-hit mechanism)","B. Methylation silencing of the gene promoter","C. Gain-of-function mutation, amplification, translocation, or overexpression of a single allele","D. Frameshift deletion causing loss of protein function"]','C','Proto-oncogenes are converted to oncogenes by gain-of-function changes: point mutations (e.g., RAS), gene amplification (e.g., HER2/ERBB2), chromosomal translocations (e.g., BCR-ABL), or insertional mutagenesis. Only one allele needs to be activated, showing dominant behaviour.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Oncogenetics','medium','mcq','Li-Fraumeni syndrome is caused by germline mutations in which gene, and what is the hallmark feature?','["A. BRCA1; predominantly breast and ovarian cancers","B. TP53; multiple early-onset cancers including sarcomas, brain tumours, breast cancer, and leukaemia","C. APC; familial adenomatous polyposis leading to colorectal cancer","D. RB1; bilateral retinoblastoma in childhood"]','B','Li-Fraumeni syndrome results from germline TP53 mutations. TP53 encodes p53, the guardian of the genome, and its loss causes susceptibility to a wide spectrum of malignancies at young ages: soft tissue sarcomas, osteosarcomas, brain tumours, breast cancer, and adrenocortical carcinomas.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Oncogenetics','medium','mcq','Familial adenomatous polyposis (FAP) is caused by germline mutations in which tumour suppressor gene?','["A. APC","B. TP53","C. BRCA2","D. MLH1"]','A','FAP is caused by germline loss-of-function mutations in APC (adenomatous polyposis coli) on chromosome 5q21. APC is a key negative regulator of the Wnt/beta-catenin signalling pathway. Affected individuals develop hundreds to thousands of colorectal polyps with near-certain progression to colorectal cancer.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Oncogenetics','medium','mcq','A woman carries a BRCA1 pathogenic variant. Compared to the general population, her lifetime risk of breast cancer is approximately:','["A. 20-30% (slightly elevated)","B. 10% (slightly below average)","C. 100% (certain to develop cancer)","D. 50-72% (markedly elevated)"]','D','BRCA1 pathogenic variant carriers have a lifetime breast cancer risk of approximately 50-72% (versus ~12% in the general population) and a 44-46% lifetime ovarian cancer risk (versus ~1.2% in the general population).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Oncogenetics','hard','mcq','Hereditary non-polyposis colorectal cancer (Lynch syndrome) is caused by mutations in which category of genes?','["A. RAS proto-oncogenes","B. DNA mismatch repair genes (MLH1, MSH2, MSH6, PMS2)","C. Tumour suppressor genes regulating cell cycle entry (RB1, CDKN2A)","D. Genes encoding growth factor receptors (EGFR, HER2)"]','B','Lynch syndrome results from germline mutations in DNA mismatch repair (MMR) genes  --  most commonly MLH1 and MSH2. Defective MMR leads to microsatellite instability (MSI) and accumulation of replication errors. Carriers have elevated risks of colorectal, endometrial, ovarian, and other cancers.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Oncogenetics','hard','mcq','The RB1 (retinoblastoma) gene product, pRb, normally functions by:','["A. Promoting cell entry into S phase by activating E2F transcription factors","B. Inhibiting cell cycle progression by binding and repressing E2F transcription factors in G1","C. Activating telomerase to maintain chromosome ends","D. Phosphorylating and degrading p53 to prevent apoptosis"]','B','pRb (retinoblastoma protein) is a tumour suppressor that in its hypophosphorylated (active) state binds and inactivates E2F transcription factors, preventing S phase entry. Mitogenic signals activate CDK4/6-cyclin D to phosphorylate pRb, releasing E2F and allowing cell cycle progression.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Oncogenetics','medium','mcq','Multiple endocrine neoplasia type 2 (MEN2) is caused by gain-of-function mutations in which gene?','["A. MEN1 (menin gene)","B. VHL tumour suppressor gene","C. RET proto-oncogene","D. NF2 (merlin gene)"]','C','MEN2 (both MEN2A and MEN2B) is caused by activating (gain-of-function) point mutations in the RET proto-oncogene on chromosome 10q11.2. Constitutive RET kinase activity drives medullary thyroid carcinoma, phaeochromocytoma, and (in MEN2A) parathyroid adenomas.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Oncogenetics','easy','mcq','Which of the following best describes a tumour suppressor gene?','["A. A gene that promotes cell proliferation when mutated","B. A gene that normally inhibits cell proliferation; both copies must be inactivated for cancer to develop","C. A gene that is only active during embryogenesis","D. A gene encoding a growth factor receptor"]','B','Tumour suppressor genes normally encode proteins that restrain cell growth, promote apoptosis, or repair DNA. They follow a recessive loss-of-function mechanism at the cellular level  --  both alleles must be inactivated (two-hit hypothesis) before growth suppression is lost.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mitochondrial Genetics','easy','mcq','Which inheritance pattern is characteristic of mitochondrial diseases?','["A. Autosomal dominant (father to son transmission)","B. Autosomal recessive (25% risk per pregnancy)","C. Maternal inheritance (transmitted only through the mother)","D. X-linked recessive (predominantly affects males)"]','C','Mitochondria are inherited almost exclusively from the mother through the egg cytoplasm. Therefore mitochondrial diseases caused by mtDNA mutations are maternally inherited  --  an affected mother transmits the disease to all her children, but an affected father does not transmit it.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mitochondrial Genetics','easy','mcq','Heteroplasmy in mitochondrial genetics refers to:','["A. The presence of only one mitochondrial DNA (mtDNA) variant in all mitochondria of a cell","B. The coexistence of two or more mtDNA variants (wild-type and mutant) within the same cell or individual","C. The fusion of two mitochondria from different parents","D. The transfer of mtDNA genes to the nuclear genome"]','B','Heteroplasmy is the coexistence of wild-type and mutant mtDNA within the same cell or individual. The proportion of mutant mtDNA affects disease severity  --  above a threshold (threshold effect), there is insufficient oxidative phosphorylation to meet cellular energy demands, causing disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mitochondrial Genetics','medium','mcq','MELAS syndrome (Mitochondrial Encephalomyopathy, Lactic Acidosis, and Stroke-like episodes) is most commonly caused by which mutation?','["A. Deletion of 4977 bp in the mitochondrial genome","B. A point mutation in the mitochondrial tRNA-Leu gene (m.3243A>G)","C. Mutation in the nuclear-encoded POLG gene","D. Trinucleotide repeat expansion in mtDNA"]','B','MELAS is most commonly caused by the m.3243A>G point mutation in the MT-TL1 gene encoding mitochondrial tRNA(Leu)(UUR). This impairs mitochondrial protein synthesis, causing defective oxidative phosphorylation with consequent stroke-like episodes, myopathy, and lactic acidosis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mitochondrial Genetics','medium','mcq','MERRF syndrome (Myoclonic Epilepsy with Ragged Red Fibres) is associated with ragged red fibres on muscle biopsy. What do these fibres represent?','["A. Increased lipid accumulation in type II muscle fibres","B. Deposits of glycogen in atrophic muscle fibres","C. Proliferation of abnormal mitochondria beneath the sarcolemma, staining red with modified Gomori trichrome stain","D. Inflammatory infiltrate around muscle fibres"]','C','Ragged red fibres represent proliferating, structurally abnormal mitochondria that accumulate beneath the sarcolemma of muscle fibres in an attempt to compensate for defective oxidative phosphorylation. They stain red with modified Gomori trichrome and are a hallmark of mitochondrial myopathies.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mitochondrial Genetics','medium','mcq','Leber hereditary optic neuropathy (LHON) primarily affects which tissues and presents with which symptom?','["A. Skeletal muscle weakness and cardiomyopathy","B. Progressive external ophthalmoplegia and ptosis","C. Sensorineural hearing loss and diabetes mellitus","D. Bilateral, painless, subacute central visual loss due to retinal ganglion cell degeneration"]','D','LHON predominantly affects retinal ganglion cells, whose high energy demands make them vulnerable to mtDNA complex I mutations (most commonly m.11778G>A, m.3460G>A, or m.14484T>C). Patients present with bilateral, painless, subacute central visual loss typically in young adult males.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mitochondrial Genetics','medium','mcq','The human mitochondrial genome encodes which of the following?','["A. All 1,000+ mitochondrial proteins","B. 13 essential subunits of the respiratory chain and ATP synthase, 22 tRNAs, and 2 rRNAs","C. Only ribosomal RNAs and no protein-coding genes","D. Transfer RNAs only; all proteins are nuclear-encoded"]','B','The mitochondrial genome (16,569 bp, circular double-stranded DNA) encodes 13 protein subunits of oxidative phosphorylation complexes (I, III, IV, V), 22 mitochondrial tRNAs, and 2 rRNAs (12S and 16S). The remaining ~1,500 mitochondrial proteins are encoded by nuclear DNA.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mitochondrial Genetics','hard','mcq','Kearns-Sayre syndrome (KSS) is characterised by the triad of progressive external ophthalmoplegia, pigmentary retinopathy, and which other feature?','["A. Cardiomyopathy alone","B. Cardiac conduction defects (heart block), onset before age 20","C. Sensorineural deafness and ataxia only","D. Dementia and stroke-like episodes"]','B','Kearns-Sayre syndrome is defined by onset before age 20 plus the triad of: progressive external ophthalmoplegia (PEO), pigmentary retinopathy, AND cardiac conduction defects (complete heart block). It is caused by large-scale mtDNA deletions and is usually sporadic.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mitochondrial Genetics','hard','mcq','Why do mitochondrial diseases often show variable clinical severity even among members of the same maternal lineage?','["A. Variable segregation of heteroplasmic mtDNA during cell division (mitotic segregation) leads to different proportions of mutant mtDNA in different individuals and tissues","B. Different nuclear DNA mutations modulate mtDNA expression differently in each person","C. X-inactivation differentially affects mitochondrial gene expression","D. Imprinting of mtDNA varies between maternal relatives"]','A','During cell division, mitochondria (and their mtDNA) are distributed randomly between daughter cells. Over time, a cell line may drift toward greater mutant or wild-type mtDNA burden (replicative segregation), explaining why relatives with the same mtDNA mutation can have widely varying clinical severity.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mitochondrial Genetics','medium','mcq','Which of the following features best distinguishes mitochondrial inheritance from autosomal dominant inheritance in a pedigree?','["A. Both patterns show vertical transmission across generations","B. Mitochondrial disorders are transmitted by affected fathers as well as mothers","C. Mitochondrial disorders show transmission exclusively through the maternal line; affected fathers do not transmit the condition","D. Mitochondrial disorders affect only females"]','C','The defining pedigree feature of mitochondrial inheritance is maternal-only transmission: all children of an affected mother may be affected (with variable severity), while children of an affected father are not affected. This distinguishes it from autosomal dominant, where father-to-son transmission occurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Mitochondrial Genetics','easy','mcq','Which organs are preferentially affected in mitochondrial diseases and why?','["A. Liver and kidney, because they metabolise most toxins","B. Brain, heart, skeletal muscle, and sensory organs  --  tissues with the highest energy demand and most dependence on oxidative phosphorylation","C. Bone marrow and lymph nodes, because of their rapid cell division","D. Skin and hair follicles, because of their high mitochondrial density"]','B','Tissues with the highest energy requirements and greatest dependence on oxidative phosphorylation are most vulnerable to mtDNA mutations: brain (encephalopathy, seizures), heart (cardiomyopathy, heart block), skeletal muscle (myopathy), retina (pigmentary retinopathy), and cochlea (sensorineural deafness).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Multifactorial Inheritance & Complex Traits','easy','mcq','Multifactorial inheritance differs from Mendelian inheritance in that multifactorial traits:','["A. Result from the combined effects of multiple genes and environmental factors, with no single locus being necessary or sufficient","B. Are determined solely by a single gene with complete penetrance","C. Follow strict dominant or recessive patterns","D. Are only transmitted on the X chromosome"]','A','Multifactorial traits arise from the additive effects of many genetic loci (polygenic) combined with environmental influences. No single gene is necessary or sufficient. Examples include type 2 diabetes, hypertension, cleft lip, and neural tube defects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Multifactorial Inheritance & Complex Traits','easy','mcq','Heritability (h^2) is defined as:','["A. The probability that an individual with the genotype will develop the disease","B. The proportion of total phenotypic variance in a population attributable to genetic variance","C. The number of genes contributing to a polygenic trait","D. The percentage of identical twins who are both affected by a disease"]','B','Heritability (h^2) measures what fraction of the observed variation in a trait within a population is due to genetic factors. h^2 ranges from 0 (entirely environmental) to 1 (entirely genetic). It is population-specific and does not apply to individuals.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Multifactorial Inheritance & Complex Traits','medium','mcq','In twin studies, concordance rates for a disease are compared between monozygotic (MZ) and dizygotic (DZ) twins. If MZ concordance is 50% and DZ concordance is 15%, this suggests:','["A. The disease is entirely environmental with no genetic component","B. Substantial genetic contribution to the disease, as MZ twins share 100% of DNA vs 50% for DZ","C. The disease is purely Mendelian dominant","D. The disease is caused by a single gene with 50% penetrance"]','B','Higher concordance in MZ twins (who share 100% of their DNA) compared to DZ twins (who share 50% on average) indicates a significant genetic component. If the disease were purely genetic (and fully penetrant), MZ concordance would be 100%; values below 100% suggest environmental contributions too.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Multifactorial Inheritance & Complex Traits','medium','mcq','Which of the following is a characteristic of multifactorial inheritance?','["A. Recurrence risk is the same regardless of how many relatives are affected","B. Recurrence risk follows a fixed 25% or 50% Mendelian ratio","C. Recurrence risk increases with the number of affected relatives and severity of the condition","D. Concordance in MZ twins is always 100%"]','C','In multifactorial disorders, empiric recurrence risk increases with the number of affected first-degree relatives and the severity of the proband''s disease, because more affected relatives imply the family carries more predisposing alleles. This distinguishes multifactorial from Mendelian recurrence patterns.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Multifactorial Inheritance & Complex Traits','medium','mcq','The liability threshold model for multifactorial diseases proposes that:','["A. Only environmental factors contribute to liability","B. An individual develops disease when their continuous liability (sum of genetic and environmental risk factors) exceeds a threshold","C. A single major gene determines all liability to the disease","D. Threshold varies only with age and not with sex"]','B','The liability threshold model proposes that the underlying liability to develop a multifactorial disease is normally distributed in the population. Disease manifests only when an individual''s total liability (genetic predisposition + environmental factors) crosses a critical threshold.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Multifactorial Inheritance & Complex Traits','medium','mcq','Pyloric stenosis is more common in males, but when a female is affected, recurrence risk for her relatives is higher than when a male is affected. This illustrates which concept?','["A. Autosomal dominant inheritance with sex limitation","B. The Carter effect  --  when the less commonly affected sex is affected, the family must carry more predisposing genes","C. Genomic imprinting affecting pyloric sphincter development","D. Mitochondrial inheritance with maternal sex bias"]','B','The Carter effect (sex-specific threshold) explains why relatives of a female proband with pyloric stenosis have a higher recurrence risk: the threshold for disease is higher in females, so an affected female must carry more predisposing alleles, which are then transmitted at higher frequency to all relatives.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Multifactorial Inheritance & Complex Traits','hard','mcq','A genome-wide association study (GWAS) identifies a SNP associated with type 2 diabetes with an odds ratio of 1.3. What does this mean?','["A. Individuals carrying the SNP are 30% more likely to develop type 2 diabetes than those without it","B. 30% of type 2 diabetes cases are caused by this SNP","C. The SNP has a penetrance of 30%","D. The SNP accounts for 30% of heritability of type 2 diabetes"]','A','An odds ratio of 1.3 means individuals carrying the risk allele have 1.3 times (30% higher) odds of developing type 2 diabetes compared to non-carriers. GWAS findings typically identify common variants with modest individual effects; they do not imply causation or explain a fixed proportion of heritability.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Multifactorial Inheritance & Complex Traits','hard','mcq','Why does concordance for schizophrenia in monozygotic twins fall short of 100% (approximately 50%) despite schizophrenia having high heritability (~80%)?','["A. MZ twins always have different mtDNA","B. Epigenetic differences, somatic mutations, gene-environment interactions, and stochastic developmental events cause phenotypic discordance despite identical DNA sequences","C. MZ twins frequently experience chromosomal non-disjunction after the embryonic split","D. Heritability estimates are unreliable and schizophrenia has no genetic component"]','B','Although MZ twins are genetically identical, discordance can arise from post-zygotic epigenetic differences (methylation patterns diverge over time), somatic copy number variations, and differential environmental exposures including prenatal events and postnatal stressors, explaining the gap between genetic identity and phenotypic concordance.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Multifactorial Inheritance & Complex Traits','medium','mcq','Which of the following is NOT typically a polygenic/multifactorial condition?','["A. Type 2 diabetes mellitus","B. Essential hypertension","C. Huntington disease","D. Cleft lip with or without cleft palate"]','C','Huntington disease is caused by a single autosomal dominant mutation (CAG repeat expansion in HTT) and follows Mendelian inheritance with very high penetrance. Type 2 diabetes, essential hypertension, and cleft lip are classic examples of multifactorial conditions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Multifactorial Inheritance & Complex Traits','easy','mcq','First-degree relatives (parents, siblings, children) of a patient with a multifactorial disorder share what proportion of their genome with the proband?','["A. 25%","B. 75%","C. 50%","D. 100%"]','C','First-degree relatives share on average 50% of their genome with each other. Second-degree relatives (grandparents, aunts/uncles, nephews/nieces) share ~25%, and third-degree relatives share ~12.5%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Pharmacogenomics','easy','mcq','CYP2D6 is a cytochrome P450 enzyme responsible for metabolising approximately 25% of all drugs. A patient who is a CYP2D6 poor metaboliser is prescribed codeine. What is the expected outcome?','["A. Excessive opioid toxicity due to excess conversion of codeine to morphine","B. Inadequate analgesia because codeine cannot be converted to its active metabolite morphine","C. Normal analgesia with no change in effect","D. Increased clearance of codeine leading to subtherapeutic levels"]','B','Codeine is a prodrug requiring CYP2D6-mediated O-demethylation to morphine (its active analgesic metabolite). Poor metabolisers (lacking functional CYP2D6) cannot convert codeine to morphine and therefore derive no analgesic benefit. Ultrarapid metabolisers face the opposite risk of toxicity.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Pharmacogenomics','easy','mcq','N-acetyltransferase 2 (NAT2) activity determines the rate of acetylation of drugs such as isoniazid. A patient who is a slow acetylator taking isoniazid is at increased risk of which adverse effect?','["A. Hepatotoxicity and peripheral neuropathy due to isoniazid accumulation","B. Treatment failure due to rapid clearance of isoniazid","C. Haemolytic anaemia","D. Serotonin syndrome"]','A','Slow acetylators have reduced NAT2 activity and accumulate isoniazid, increasing the risk of dose-dependent adverse effects: peripheral neuropathy (preventable with pyridoxine supplementation) and hepatotoxicity. Rapid acetylators may have subtherapeutic levels and treatment failure.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Pharmacogenomics','medium','mcq','CYP2C19 poor metabolisers taking clopidogrel (an antiplatelet prodrug) are at increased risk of which clinical event?','["A. Bleeding complications due to excessive platelet inhibition","B. Thromboembolic events (stent thrombosis, MI) due to inadequate antiplatelet effect","C. Hepatic failure","D. QT prolongation and arrhythmia"]','B','Clopidogrel is a prodrug requiring CYP2C19-mediated bioactivation to its active thiol metabolite. CYP2C19 poor metabolisers (common in East Asian populations) produce insufficient active drug, leading to inadequate platelet inhibition and increased risk of cardiovascular events including stent thrombosis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Pharmacogenomics','medium','mcq','G6PD deficiency is an X-linked pharmacogenomic condition. Which drug class triggers haemolytic anaemia in G6PD-deficient individuals?','["A. Beta-blockers","B. ACE inhibitors","C. Statins","D. Primaquine, dapsone, and other oxidant drugs"]','D','G6PD (glucose-6-phosphate dehydrogenase) protects red blood cells from oxidative stress by generating NADPH. Deficient individuals exposed to oxidant drugs (primaquine, dapsone, nitrofurantoin, certain sulfonamides) or fava beans suffer acute haemolytic anaemia due to inability to neutralise reactive oxygen species.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Pharmacogenomics','medium','mcq','HLA-B*57:01 genotyping is performed before initiating which antiretroviral drug to prevent severe hypersensitivity reactions?','["A. Efavirenz","B. Abacavir","C. Tenofovir","D. Ritonavir"]','B','HLA-B*57:01 is strongly associated with abacavir hypersensitivity syndrome (AHS), a potentially life-threatening systemic reaction. Pre-treatment HLA-B*57:01 screening is recommended (and in many guidelines mandatory) to identify at-risk patients and avoid abacavir in carriers of this allele.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Pharmacogenomics','medium','mcq','Thiopurine methyltransferase (TPMT) genotyping is clinically important when prescribing which drugs?','["A. Warfarin and acenocoumarol","B. Azathioprine, 6-mercaptopurine, and thioguanine","C. Methotrexate and fluorouracil","D. Imatinib and erlotinib"]','B','TPMT catalyses methylation of thiopurine drugs (azathioprine, 6-mercaptopurine, thioguanine), inactivating them. TPMT-deficient patients accumulate cytotoxic thioguanine nucleotides, risking severe, potentially fatal myelosuppression. Pre-treatment TPMT testing allows dose reduction or drug avoidance.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Pharmacogenomics','hard','mcq','A patient on warfarin requires unusually low doses to achieve therapeutic anticoagulation (INR 2-3). Pharmacogenomic testing reveals variants in which two genes most likely to explain this finding?','["A. CYP2D6 (poor metaboliser) and TPMT (deficient)","B. CYP2C9 (reduced function alleles) and VKORC1 (warfarin-sensitivity haplotype)","C. CYP3A4 (ultrarapid metaboliser) and factor V Leiden","D. NAT2 (slow acetylator) and HLA-B*57:01"]','B','Warfarin dose requirement is strongly influenced by CYP2C9 (which metabolises the more potent S-warfarin) and VKORC1 (encoding vitamin K epoxide reductase, warfarin''s target). CYP2C9 loss-of-function alleles (*2, *3) and the VKORC1 -1639G>A (warfarin-sensitivity) haplotype together account for ~40% of warfarin dose variance.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Pharmacogenomics','hard','mcq','Malignant hyperthermia triggered by volatile anaesthetics (e.g., halothane, sevoflurane) and succinylcholine is caused by mutations in which gene?','["A. SCN4A (sodium channel)","B. CACNA1A (voltage-gated calcium channel)","C. ATP2A2 (SERCA pump)","D. RYR1 (ryanodine receptor type 1 in skeletal muscle)"]','D','Malignant hyperthermia susceptibility is caused by autosomal dominant mutations in RYR1 (ryanodine receptor 1), the calcium release channel of the sarcoplasmic reticulum in skeletal muscle. Triggering agents cause uncontrolled calcium release, leading to sustained muscle contraction, hyperthermia, rhabdomyolysis, and potentially death if untreated with dantrolene.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Pharmacogenomics','medium','mcq','CYP3A4/5 enzymes metabolise approximately 50% of all marketed drugs. Which statement about CYP3A4 inducers is correct?','["A. CYP3A4 inducers decrease the metabolism of co-administered drugs, raising their plasma levels","B. CYP3A4 inducers (e.g., rifampicin, carbamazepine) increase enzyme expression, accelerating metabolism of substrates and potentially causing therapeutic failure","C. CYP3A4 inducers only affect drugs metabolised by CYP2D6","D. CYP3A4 induction is purely a pharmacogenomic (genetic) phenomenon with no environmental component"]','B','CYP3A4 inducers (rifampicin, St John''s wort, carbamazepine, phenytoin) upregulate CYP3A4 expression via nuclear receptors (PXR, CAR), increasing metabolism of CYP3A4 substrates. This reduces plasma levels of drugs such as oral contraceptives, antiretrovirals, cyclosporin, and statins, risking therapeutic failure.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Genetics','Pharmacogenomics','easy','mcq','The goal of personalised medicine (precision medicine) in pharmacogenomics is best described as:','["A. Prescribing the same drug and dose to all patients with the same diagnosis","B. Using gene therapy to cure all genetic diseases before drug treatment is needed","C. Restricting expensive medications to patients with specific ethnic backgrounds","D. Tailoring drug choice and dosing to an individual''s genetic profile to maximise efficacy and minimise adverse effects"]','D','Personalised medicine uses an individual''s genetic information (pharmacogenomic profile) alongside clinical data to select the most appropriate drug at the optimal dose, minimising adverse drug reactions and improving therapeutic outcomes compared to a one-size-fits-all approach.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
